import type { Lang } from "@/lib/i18n/config";
import type { Race } from "@/lib/data";
import type { Bi } from "@/lib/i18n/config";

/**
 * Wiki data model and the pure helpers behind the wiki UI.
 * The data itself is generated by scripts/wiki/build-wiki-data.js into data/generated/wiki.json.
 */

export interface Weapon {
  id: string;
  /** In-game Korean name, when the game has one. */
  nameKo?: string | null;
  targets: string | null;
  range: number | null;
  cd: number | null;
  count: number;
  dmg: number | null;
  bonus: { type: string; dmg: number }[];
  dps: number | null;
  dpsBonus: number | null;
  splash: number | null;
}

export interface Ability {
  id: string;
  nameKo?: string | null;
  energy?: number | null;
  minerals?: number | null;
  gas?: number | null;
  cd?: number | null;
  range?: number | null;
}

/** One unit's values in one version. `prov` records where each number came from: mod, base, curated or partial. */
export interface Block {
  hp: number | null;
  shields: number | null;
  armor: number | null;
  shieldArmor: number | null;
  energy: { start: number | null; max: number | null } | null;
  speed: number | null;
  sight: number | null;
  radius: number | null;
  cargo: number | null;
  cost: { minerals: number | null; gas: number | null; supply: number | null; time: number | null };
  attrs: string[] | null;
  producer: string | null;
  requires: string[] | null;
  move: string | null;
  weapons: Weapon[] | null;
  text?: { ground: string; air: string; role: string; range: number };
  abilities: Ability[] | null;
  prov: Record<string, string>;
  timeKind?: string;
}

export type Group = "worker" | "ground" | "air" | "mode";

export interface BaseUnit {
  id: string;
  race: Race;
  ko: string;
  en: string;
  group: Group;
  icon: string | null;
  v: Record<string, Block>;
}

/** Authored ko/en text for an added unit (scripts/wiki/curated/unit-notes.json). Numbers are never written here. */
export interface UnitNotes {
  reviewed: boolean;
  role: Bi;
  producer: Bi;
  requires: Bi;
  diff: { item: Bi; pair: Bi; unit: Bi }[];
}

export interface ExtUnit {
  id: string;
  race: Race;
  ko: string;
  en: string;
  icon: string;
  pairKo: string;
  pairEn: string;
  pairId: string;
  notes: UnitNotes;
  v: Record<string, Block>;
}

/** A research upgrade: cost and times come from the mod, Korean text is the in-game text. */
export interface Upgrade {
  id: string;
  units: string[];
  icon: string;
  name: Bi;
  effect: Bi;
  building: Bi | null;
  minerals: number | null;
  gas: number | null;
  time: number | null;
}

export interface WikiVersionInfo {
  id: string;
  status: "current" | "previous" | "archive";
  source: string;
}

export interface WikiData {
  versions: WikiVersionInfo[];
  /** Stated changes per version and unit id: the value before that version. See scripts/wiki/curated/known-changes.json. */
  changes: Record<string, Record<string, ChangeMap>>;
  base: BaseUnit[];
  units: ExtUnit[];
  upgrades: Upgrade[];
}

/** A unit resolved for one version, with the values that differ from the preceding version in `ch` (old values). */
export interface Row extends Block {
  id: string;
  kind: "base" | "ext";
  race: Race;
  ko: string;
  en: string;
  icon: string | null;
  group: Group | "ext";
  /** Largest weapon range, or the curated range for units whose weapons are not in the XML. */
  rng: number | null;
  ch: ChangeMap;
  raw: BaseUnit | ExtUnit;
}

export type ChangeMap = {
  hp?: number;
  shields?: number;
  armor?: number;
  shieldArmor?: number;
  speed?: number;
  sight?: number;
  radius?: number;
  cargo?: number;
  minerals?: number;
  gas?: number;
  supply?: number;
  time?: number;
  attrs?: string[];
};

/**
 * Resolve one unit for `ver`. `ch` holds the values this version changed (the value before), taken from the
 * stated changes in the patch notes rather than from comparing snapshots, which is not reliable.
 */
export function buildRow(u: BaseUnit | ExtUnit, kind: "base" | "ext", ver: string, changes: WikiData["changes"]): Row {
  const cur = u.v[ver];
  const rng = cur.weapons && cur.weapons.length ? Math.max(0, ...cur.weapons.map((x) => x.range ?? 0)) : (cur.text?.range ?? null);
  return {
    ...cur,
    id: u.id,
    kind,
    race: u.race,
    ko: u.ko,
    en: u.en,
    icon: u.icon,
    group: kind === "ext" ? "ext" : (u as BaseUnit).group,
    rng,
    ch: changes[ver]?.[u.id] ?? {},
    raw: u,
  };
}

/* ---------- labels ---------- */

type Pair = readonly [string, string];
const pick = (lang: Lang, p: Pair) => (lang === "ko" ? p[0] : p[1]);

const ATTR: Record<string, Pair> = {
  Light: ["경장갑", "Light"],
  Armored: ["중장갑", "Armored"],
  Biological: ["생체", "Biological"],
  Mechanical: ["기계", "Mechanical"],
  Massive: ["거대", "Massive"],
  Psionic: ["사이오닉", "Psionic"],
  Robotic: ["로봇", "Robotic"],
  Hover: ["호버", "Hover"],
  Structure: ["건물", "Structure"],
  Summoned: ["소환", "Summoned"],
  Hero: ["영웅", "Hero"],
};
export const attrName = (lang: Lang, a: string) => (ATTR[a] ? pick(lang, ATTR[a]) : a);

const TARGETS: Record<string, Pair> = { ground: ["지상", "Ground"], air: ["공중", "Air"], any: ["지상/공중", "Ground/Air"] };
export const targetName = (lang: Lang, t: string | null) => (t && TARGETS[t] ? pick(lang, TARGETS[t]) : t);

const GROUPS: Record<string, Pair> = {
  worker: ["일꾼", "Worker"],
  ground: ["지상", "Ground"],
  air: ["공중", "Air"],
  mode: ["모드 전환형", "Mode form"],
  ext: ["BPM 추가", "BPM added"],
};
export const groupName = (lang: Lang, g: string) => (GROUPS[g] ? pick(lang, GROUPS[g]) : g);

/** Base-game building and requirement names, Korean. English shows the ids as they are. */
const BUILDINGS_KO: Record<string, string> = {
  "Command Center": "사령부", Barracks: "병영", "Tech Lab": "기술실", "Barracks Tech Lab": "병영 기술실",
  "Ghost Academy": "유령 사관학교", Factory: "군수공장", Armory: "무기고", "Factory Tech Lab": "군수공장 기술실",
  Starport: "우주공항", "Fusion Core": "융합로", Nexus: "연결체", Gateway: "관문", "Cybernetics Core": "인공제어소",
  "Templar Archive": "기사단 문서보관소", "Dark Shrine": "암흑 성소", "High Templar": "고위 기사",
  "Robotics Facility": "로봇공학시설", "Robotics Bay": "로봇공학지원소", Stargate: "우주관문", "Fleet Beacon": "함대 신호소",
  Mothership: "모선", Larva: "애벌레", "Spawning Pool": "산란못", Zergling: "저글링", "Baneling Nest": "맹독충 둥지",
  "Roach Warren": "바퀴 소굴", Roach: "바퀴", "Hydralisk Den": "히드라리스크 굴", Hydralisk: "히드라리스크",
  "Lurker Den MP": "가시지옥 굴", "Infestation Pit": "감염 구덩이", "Ultralisk Cavern": "울트라리스크 동굴",
  Hatchery: "부화장", Overlord: "대군주", Lair: "군락", Spire: "둥지탑", Corruptor: "타락귀", "Greater Spire": "거대 둥지탑",
  Hive: "산란장", Ground: "지상", Fly: "비행", CliffJumper: "절벽 이동", Colossus: "거신",
};
export const buildingName = (lang: Lang, s: string) => (lang === "ko" && BUILDINGS_KO[s] ? BUILDINGS_KO[s] : s);

export const fmt = (v: unknown): string => (v === null || v === undefined || v === "" ? "-" : String(v));

export function weaponText(lang: Lang, w: Weapon): string {
  const dmg = w.dmg === null ? "-" : String(w.dmg);
  const hits = w.count > 1 ? `×${w.count}` : "";
  const bonus = w.bonus.map((x) => ` (+${x.dmg} ${attrName(lang, x.type)})`).join("");
  return dmg + hits + bonus;
}

/** Difference between two numbers for the pair view: direction and label. */
export function delta(a: unknown, b: unknown): { dir: "up" | "down" | "flat" | "text"; label: string } {
  const x = typeof a === "number" ? a : null;
  const y = typeof b === "number" ? b : null;
  if (x === null || y === null) return { dir: "text", label: "" };
  const d = Math.round((y - x) * 100) / 100;
  if (d === 0) return { dir: "flat", label: "0" };
  return { dir: d > 0 ? "up" : "down", label: (d > 0 ? "+" : "") + d };
}

/**
 * Display name of a weapon. Korean uses the in-game name; when the game has none (or for English, which has no in-game
 * name source) the weapon is labelled by what it hits, never by its data id.
 */
export function weaponName(lang: Lang, w: Weapon, all: Weapon[]): string {
  if (lang === "ko" && w.nameKo) return w.nameKo;
  const same = all.filter((x) => x.targets === w.targets);
  const base = w.targets === "ground" ? ["지상 공격", "Ground attack"] : w.targets === "air" ? ["공중 공격", "Air attack"] : ["공격", "Attack"];
  return `${pick(lang, base as unknown as Pair)}${same.length > 1 ? ` ${same.indexOf(w) + 1}` : ""}`;
}

/** Display name of an ability: the in-game Korean name, otherwise the readable data name. */
export const abilityName = (lang: Lang, a: { id: string; nameKo?: string | null }) => (lang === "ko" && a.nameKo ? a.nameKo : a.id);
